/*
 * The published MessagePack test suite: dist/msgpack-test-suite.json of https://github.com/kawanet/msgpack-test-suite at
 * commit e04f6edeaae589c768d6b70fcce80aa786b7800e (2018-10-18), MIT licence (LICENSE in this folder). 15 groups, 85
 * cases, 233 encodings. Every value is kept in the suite's own notation: binaries and extension data as hex bytes
 * joined by dashes, timestamps as [seconds, nanoseconds], the big numbers as a decimal string under `bignum`, and an
 * extension as [type, hex data]. Generated by a script from the suite's JSON, never written by hand and never produced
 * by this package. See UPSTREAM.md.
 */

/** One case: the group file it comes from, the kind of value, the value and every encoding that must decode to it. */
export interface SuiteCase {
  group: string;
  kind: 'nil' | 'bool' | 'binary' | 'number' | 'bignum' | 'string' | 'array' | 'map' | 'timestamp' | 'ext';
  value: unknown;
  /** Only the big number cases: the number the suite also gives, which a double holds exactly or not. */
  number?: number;
  encodings: string[];
}

